"""
Constraint extractor: extract structured math constraints from LLM reasoning traces.
Input: reasoning trace string
Output: list of constraint dicts with type, expression, z3_formula, source_step
Dependencies: json, re, openai (optional)
"""
from __future__ import annotations

import json
import logging
import re
import time
import random
from abc import ABC, abstractmethod
from concurrent.futures import ThreadPoolExecutor, as_completed
from dataclasses import dataclass, field

logger = logging.getLogger(__name__)

EXTRACTION_PROMPT = '''Extract mathematical constraints from this reasoning trace as a JSON object.

Rules:
- type: "equation", "inequality", or "predicate"
- expression: human-readable, e.g. "x + y == 14"
- z3_formula: Python Z3 syntax (==, !=, <, >, +, -, *, /, **)
- source_step: step number where the constraint appears
- Use variable names from the trace

Output ONLY the JSON below, nothing else:
{{"constraints": [{{"type": "equation", "expression": "x + y == 14", "z3_formula": "x + y == 14", "source_step": 1}}], "answer": "final_answer", "variables": ["x", "y"]}}

Trace:
{trace}'''

LOGIC_EXTRACTION_PROMPT = '''Extract logical constraints from this reasoning trace about a logic problem.

The problem has facts (base assertions), rules (grounded implications), and derived conclusions.
Convert each into a Z3 boolean formula.

Variable naming:
- Unary property: property_entity (e.g., kind_anne, red_charlie, round_fiona)
- Binary relation: relation_subject_object (e.g., eats_bear_squirrel, likes_lion_cat)
- Use lowercase with underscores only, no spaces or special characters

Constraint types:
- "fact": a given assertion, e.g., kind_anne == True
- "rule": a grounded implication over specific entities, e.g., Implies(kind_anne, nice_anne)
- "derived": an inferred conclusion from facts + rules, e.g., nice_anne == True

Z3 operators:
- Implies(a, b) for if-then rules
- And(a, b, ...) for conjunctive conditions
- Or(a, b, ...) for disjunctive conditions
- Not(a) for negation
- == True / == False for boolean assertions

Output ONLY the JSON below, nothing else:
{{"constraints": [{{"type": "fact", "expression": "kind(anne)", "z3_formula": "kind_anne == True", "source_step": 1}}], "answer": "True or False or Unknown", "variables": ["kind_anne"]}}

Example 1:
Trace: "Anne is kind. Kind things are nice. Therefore Anne is nice. The answer is True."
Output:
{{"constraints": [
  {{"type": "fact", "expression": "kind(anne)", "z3_formula": "kind_anne == True", "source_step": 1}},
  {{"type": "rule", "expression": "kind(X) -> nice(X)", "z3_formula": "Implies(kind_anne, nice_anne)", "source_step": 2}},
  {{"type": "derived", "expression": "nice(anne)", "z3_formula": "nice_anne == True", "source_step": 3}}
], "answer": "True", "variables": ["kind_anne", "nice_anne"]}}

Example 2:
Trace: "The bear eats the squirrel. If someone eats the squirrel then the squirrel is red. So the squirrel is red. The answer is True."
Output:
{{"constraints": [
  {{"type": "fact", "expression": "eats(bear, squirrel)", "z3_formula": "eats_bear_squirrel == True", "source_step": 1}},
  {{"type": "rule", "expression": "eats(X, squirrel) -> red(squirrel)", "z3_formula": "Implies(eats_bear_squirrel, red_squirrel)", "source_step": 2}},
  {{"type": "derived", "expression": "red(squirrel)", "z3_formula": "red_squirrel == True", "source_step": 3}}
], "answer": "True", "variables": ["eats_bear_squirrel", "red_squirrel"]}}

Example 3 (multi-condition rule):
Trace: "Gary is big. Gary is quiet. Big things are smart. Quiet, cold things are white. Gary is smart. But Gary is not cold. So we cannot determine if Gary is furry. The answer is Unknown."
Output:
{{"constraints": [
  {{"type": "fact", "expression": "big(gary)", "z3_formula": "big_gary == True", "source_step": 1}},
  {{"type": "fact", "expression": "quiet(gary)", "z3_formula": "quiet_gary == True", "source_step": 2}},
  {{"type": "rule", "expression": "big(X) -> smart(X)", "z3_formula": "Implies(big_gary, smart_gary)", "source_step": 3}},
  {{"type": "rule", "expression": "quiet(X) & cold(X) -> white(X)", "z3_formula": "Implies(And(quiet_gary, cold_gary), white_gary)", "source_step": 4}},
  {{"type": "derived", "expression": "smart(gary)", "z3_formula": "smart_gary == True", "source_step": 5}}
], "answer": "Unknown", "variables": ["big_gary", "quiet_gary", "smart_gary", "cold_gary", "white_gary"]}}

Trace:
{trace}'''

_MATH_TYPES = {"equation", "inequality", "predicate"}
_LOGIC_TYPES = {"fact", "rule", "derived"}



def _retry_with_backoff(func, max_retries=2, base_delay=0.5):
    for attempt in range(max_retries + 1):
        try:
            return func()
        except Exception as e:
            if attempt == max_retries:
                raise
            delay = base_delay * (2 ** attempt) + random.uniform(0, 0.5)
            logger.warning("Retry %d/%d after %.1fs: %s", attempt + 1, max_retries, delay, e)
            time.sleep(delay)


class LLMBackend(ABC):
    """LLM abstract base class"""
    @abstractmethod
    def call(self, prompt: str) -> str:
        ...


class VLLMBackend(LLMBackend):
    """OpenAI-compatible API backend for local vLLM"""

    def __init__(self, base_url: str = "http://localhost:8000/v1", model: str | None = None,
                 max_tokens: int = 4096):
        from openai import OpenAI
        self.client = OpenAI(base_url=base_url, api_key="[REDACTED]")
        self.max_tokens = max_tokens
        if model is None:
            models = self.client.models.list()
            self.model = models.data[0].id
        else:
            self.model = model

    def call(self, prompt: str) -> str:
        return _retry_with_backoff(lambda: self.client.chat.completions.create(
            model=self.model,
            messages=[{"role": "user", "content": prompt}],
            temperature=0.3,
            max_tokens=self.max_tokens,
        ).choices[0].message.content or "")

    def batch_call(self, prompts: list[str], max_workers: int = 4) -> list[str]:
        results = [None] * len(prompts)
        with ThreadPoolExecutor(max_workers=max_workers) as executor:
            future_to_idx = {executor.submit(self.call, p): i for i, p in enumerate(prompts)}
            for future in as_completed(future_to_idx):
                idx = future_to_idx[future]
                try:
                    results[idx] = future.result()
                except Exception as e:
                    logger.error("Extraction %d failed: %s", idx, e)
                    results[idx] = ""
        return results


class MockLLM(LLMBackend):
    """Returns pre-set responses for testing."""

    def __init__(self, responses: list[str] | None = None, domain: str = "math"):
        self._responses = responses or []
        self._idx = 0
        self._domain = domain

    def call(self, prompt: str) -> str:
        if self._responses:
            resp = self._responses[self._idx % len(self._responses)]
            self._idx += 1
            return resp
        if self._domain == "logic":
            return json.dumps({"constraints": [
                {"type": "fact", "expression": "kind(anne)", "z3_formula": "kind_anne == True", "source_step": 1},
                {"type": "rule", "expression": "kind(X) -> nice(X)", "z3_formula": "Implies(kind_anne, nice_anne)", "source_step": 2},
                {"type": "derived", "expression": "nice(anne)", "z3_formula": "nice_anne == True", "source_step": 3},
            ], "answer": "True", "variables": ["kind_anne", "nice_anne"]})
        return json.dumps({"constraints": [
            {"type": "equation", "expression": "x - 7", "z3_formula": "x == 7", "source_step": 1},
            {"type": "equation", "expression": "x + 5 - 12", "z3_formula": "x + 5 == 12", "source_step": 2},
        ], "answer": "7", "variables": ["x"]})


class APIBasedLLM(LLMBackend):
    """LLM backend using OpenAI-compatible API (e.g. vLLM server)."""

    def __init__(self, base_url: str = "http://localhost:8000/v1",
                 api_key: [REDACTED] = "EMPTY", model: str | None = None,
                 temperature: float = 0.1, max_tokens: int = 4096):
        import openai
        self.client = openai.OpenAI(base_url=base_url, api_key=[REDACTED]
        self.temperature = temperature
        self.max_tokens = max_tokens
        if model:
            self.model = model
        else:
            models = self.client.models.list()
            self.model = models.data[0].id

    def call(self, prompt: str) -> str:
        return _retry_with_backoff(lambda: self.client.chat.completions.create(
            model=self.model,
            messages=[{"role": "user", "content": prompt}],
            temperature=self.temperature,
            max_tokens=self.max_tokens,
        ).choices[0].message.content or "")

    def batch_call(self, prompts: list[str], max_workers: int = 4) -> list[str]:
        results = [None] * len(prompts)
        with ThreadPoolExecutor(max_workers=max_workers) as executor:
            future_to_idx = {executor.submit(self.call, p): i for i, p in enumerate(prompts)}
            for future in as_completed(future_to_idx):
                idx = future_to_idx[future]
                try:
                    results[idx] = future.result()
                except Exception as e:
                    logger.error("Extraction %d failed: %s", idx, e)
                    results[idx] = ""
        return results


@dataclass
class ExtractionStats:
    success: int = 0
    fail_json_parse: int = 0
    fail_empty: int = 0
    fail_invalid_expr: int = 0

    @property
    def total_fail(self) -> int:
        return self.fail_json_parse + self.fail_empty + self.fail_invalid_expr


class ConstraintExtractor:
    def __init__(self, llm: LLMBackend | None = None, parse_retries: int = 1,
                 domain: str = "math"):
        self.llm = llm or MockLLM()
        self.stats = ExtractionStats()
        self.parse_retries = parse_retries
        self.domain = domain

    def _build_prompt(self, trace: str) -> str:
        template = LOGIC_EXTRACTION_PROMPT if self.domain == "logic" else EXTRACTION_PROMPT
        return template.format(trace=trace)

    @staticmethod
    def _strip_thinking(text: str) -> str:
        """Remove <think>...</think> blocks, handling truncated tags."""
        idx = text.find('</think>')
        if idx != -1:
            return text[idx + len('</think>'):].strip()
        # Truncated thinking: <think> present but no </think> — entire output is thinking
        idx = text.find('<think>')
        if idx != -1:
            return ''
        return text

    @staticmethod
    def _extract_json_str(text: str) -> str | None:
        """Try multiple strategies to extract a JSON object string."""
        # Strategy 1: fenced code block ```json ... ```
        m = re.search(r'```(?:json)?\s*(.*?)```', text, re.DOTALL)
        if m:
            return m.group(1).strip()
        # Strategy 2: find outermost { ... } braces
        start = text.find('{')
        if start != -1:
            depth = 0
            for i in range(start, len(text)):
                if text[i] == '{':
                    depth += 1
                elif text[i] == '}':
                    depth -= 1
                    if depth == 0:
                        return text[start:i + 1]
        return None

    @staticmethod
    def _repair_json(s: str) -> str:
        """Fix common JSON errors from LLMs."""
        # Remove trailing commas before } or ]
        s = re.sub(r',\s*([}\]])', r'\1', s)
        # Replace single quotes with double quotes
        s = s.replace("'", '"')
        return s

    def _parse_response(self, raw: str, trace: str) -> list[dict]:
        text = self._strip_thinking(raw.strip())
        if not text:
            logger.warning("Empty after stripping thinking for trace: %s...", trace[:80])
            self.stats.fail_json_parse += 1
            return []

        json_str = self._extract_json_str(text)
        if json_str is None:
            logger.warning("No JSON found in response for trace: %s...", trace[:80])
            self.stats.fail_json_parse += 1
            return []

        data = None
        try:
            data = json.loads(json_str)
        except json.JSONDecodeError:
            try:
                data = json.loads(self._repair_json(json_str))
            except json.JSONDecodeError:
                logger.warning("JSON parse failed for trace: %s...", trace[:80])
                self.stats.fail_json_parse += 1
                return []

        constraints = data.get("constraints", [])
        if not constraints:
            self.stats.fail_empty += 1
            return []

        valid = []
        for c in constraints:
            if not all(k in c for k in ("type", "expression", "z3_formula", "source_step")):
                continue
            valid_types = _LOGIC_TYPES if self.domain == "logic" else _MATH_TYPES
            if c["type"] not in valid_types:
                continue
            valid.append(c)

        if not valid:
            self.stats.fail_invalid_expr += 1
            return []

        self.stats.success += 1
        return valid

    def extract(self, trace: str) -> list[dict]:
        prompt = self._build_prompt(trace)
        for attempt in range(self.parse_retries + 1):
            raw = self.llm.call(prompt)
            result = self._parse_response(raw, trace)
            if result or attempt == self.parse_retries:
                return result
            logger.info("Re-extracting constraints (attempt %d/%d)", attempt + 1, self.parse_retries)
        return []

    def extract_batch(self, traces: list[str]) -> list[list[dict]]:
        if hasattr(self.llm, 'batch_call'):
            prompts = [self._build_prompt(t) for t in traces]
            raw_results = self.llm.batch_call(prompts)
            return [self._parse_response(raw, trace)
                    for raw, trace in zip(raw_results, traces)]
        return [self.extract(t) for t in traces]

"""
Z3-based weighted partial MAX-SAT solver for constraint consensus.
Input: multi-trace constraint lists (list of list of dicts)
Output: optimal satisfiable constraint subset, excluded contradictions, per-answer scores
Dependencies: z3-solver
"""
from __future__ import annotations

import logging
import re
import time
from dataclasses import dataclass, field

import z3

logger = logging.getLogger(__name__)

_BOOL_INDICATORS = re.compile(r'\bImplies\s*\(|==\s*True|==\s*False|\bNot\s*\(|\bAnd\s*\(|\bOr\s*\(')


def _is_boolean_formula(formula_str: str) -> bool:
    """Detect whether a formula uses boolean logic (vs arithmetic)."""
    return bool(_BOOL_INDICATORS.search(formula_str))


def _preprocess_formula(formula_str: str) -> str:
    """Normalize common LLM output patterns before z3 eval."""
    s = formula_str.strip()
    # Sum -> sum
    s = re.sub(r'\bSum\b', 'sum', s)
    # sum([x1, x2, ...]) -> sum(x1, x2, ...)
    s = re.sub(r'\bsum\(\[([^\[\]]*)\]\)', r'sum(\1)', s)
    # pow(a, b) -> (a)**(b)
    s = re.sub(r'\bpow\(([^,]+),\s*([^)]+)\)', r'(\1)**(\2)', s)
    # Abs -> abs
    s = re.sub(r'\bAbs\b', 'abs', s)
    return s


def parse_z3_formula(formula_str: str, var_type: str = "auto") -> z3.ExprRef | None:
    """Safely parse a string into a z3 expression.

    Supports:
      - Arithmetic: +, -, *, /, **, ==, !=, <, >, <=, >= (Real variables)
      - Boolean: Implies, And, Or, Not, == True/False (Bool variables)
      - Functions: sum, max, min, abs (z3-compatible wrappers)
    Auto-declares unknown variables as z3.Real or z3.Bool based on context.
    Returns None on parse failure or non-boolean result.
    """
    if not formula_str or not formula_str.strip():
        return None

    formula_str = _preprocess_formula(formula_str)

    use_bool = (var_type == "bool") or (var_type == "auto" and _is_boolean_formula(formula_str))

    tokens = set(re.findall(r'\b([a-zA-Z_]\w*)\b', formula_str))
    reserved = {
        'True', 'False', 'And', 'Or', 'Not', 'Implies', 'If',
        'abs', 'Abs', 'Bool', 'Real', 'Int',
        'sum', 'Sum', 'max', 'min', 'len', 'int', 'Mod', 'pow',
    }
    var_names = tokens - reserved

    ns: dict = {}
    for name in var_names:
        ns[name] = z3.Bool(name) if use_bool else z3.Real(name)

    ns['And'] = z3.And
    ns['Or'] = z3.Or
    ns['Not'] = z3.Not
    ns['Implies'] = z3.Implies
    ns['If'] = z3.If
    ns['Bool'] = z3.Bool
    ns['Real'] = z3.Real
    ns['Int'] = z3.Int
    ns['True'] = True
    ns['False'] = False
    ns['Mod'] = lambda a, b: a % b
    ns['pow'] = lambda a, b: a ** b

    ns['abs'] = lambda x: z3.If(x >= 0, x, -x) if isinstance(x, z3.ArithRef) else abs(x)

    def _z3_sum(*args):
        items = []
        for a in args:
            if hasattr(a, '__iter__') and not isinstance(a, z3.ExprRef):
                items.extend(a)
            else:
                items.append(a)
        if not items:
            return 0
        result = items[0]
        for item in items[1:]:
            result = result + item
        return result

    def _z3_max(*args):
        items = []
        for a in args:
            if hasattr(a, '__iter__') and not isinstance(a, z3.ExprRef):
                items.extend(a)
            else:
                items.append(a)
        if not items:
            raise ValueError("max() requires at least one argument")
        result = items[0]
        for item in items[1:]:
            if isinstance(result, z3.ExprRef) or isinstance(item, z3.ExprRef):
                result = z3.If(result >= item, result, item)
            else:
                result = result if result >= item else item
        return result

    def _z3_min(*args):
        items = []
        for a in args:
            if hasattr(a, '__iter__') and not isinstance(a, z3.ExprRef):
                items.extend(a)
            else:
                items.append(a)
        if not items:
            raise ValueError("min() requires at least one argument")
        result = items[0]
        for item in items[1:]:
            if isinstance(result, z3.ExprRef) or isinstance(item, z3.ExprRef):
                result = z3.If(result <= item, result, item)
            else:
                result = result if result <= item else item
        return result

    ns['sum'] = _z3_sum
    ns['Sum'] = _z3_sum
    ns['max'] = _z3_max
    ns['min'] = _z3_min
    ns['len'] = len
    ns['int'] = lambda x: x

    try:
        result = eval(formula_str, {"__builtins__": {}}, ns)
        if isinstance(result, z3.ExprRef) and z3.is_bool(result):
            return result
        if isinstance(result, bool):
            return z3.BoolVal(result)
        return None
    except Exception as e:
        logger.debug("Failed to parse z3 formula '%s': %s", formula_str, e)
        return None


def check_equivalence(f1: z3.ExprRef, f2: z3.ExprRef, timeout_ms: int = 1000) -> bool:
    """Check if two z3 formulas are logically equivalent (f1 ⟺ f2)."""
    if not z3.is_bool(f1) or not z3.is_bool(f2):
        return False
    s = z3.Solver()
    s.set("timeout", timeout_ms)
    s.add(z3.Not(f1 == f2))
    result = s.check()
    return result == z3.unsat


@dataclass
class UniqueConstraint:
    expression: str
    z3_formula: z3.ExprRef
    weight: int  # cross-trace frequency
    source_traces: list[int] = field(default_factory=list)

    def __repr__(self) -> str:
        return f"UniqueConstraint(expr='{self.expression}', w={self.weight}, traces={self.source_traces})"


@dataclass
class MaxSATResult:
    satisfied: list[UniqueConstraint]
    excluded: list[UniqueConstraint]
    total_weight: int
    solve_time_ms: float


class ConstraintDeduplicator:
    """Deduplicate constraints across traces using z3 equivalence checking."""

    def __init__(self, equiv_timeout_ms: int = 1000):
        self.equiv_timeout_ms = equiv_timeout_ms

    def deduplicate(self, all_constraints: list[list[dict]]) -> list[UniqueConstraint]:
        """Merge equivalent constraints across K traces.

        Args:
            all_constraints: K lists of constraint dicts, one per trace.
        Returns:
            Deduplicated list with frequency weights.
        """
        unique: list[UniqueConstraint] = []

        for trace_idx, trace_constraints in enumerate(all_constraints):
            for c in trace_constraints:
                z3_f = parse_z3_formula(c.get("z3_formula", ""))
                if z3_f is None:
                    logger.debug("Skipping unparseable constraint: %s", c.get("z3_formula"))
                    continue

                merged = False
                for uc in unique:
                    try:
                        if check_equivalence(uc.z3_formula, z3_f, self.equiv_timeout_ms):
                            uc.weight += 1
                            if trace_idx not in uc.source_traces:
                                uc.source_traces.append(trace_idx)
                            merged = True
                            break
                    except Exception:
                        continue

                if not merged:
                    unique.append(UniqueConstraint(
                        expression=c.get("expression", ""),
                        z3_formula=z3_f,
                        weight=1,
                        source_traces=[trace_idx],
                    ))

        return unique


class MaxSATSolver:
    """Weighted partial MAX-SAT solver using z3.Optimize."""

    def solve(self, unique_constraints: list[UniqueConstraint], timeout_ms: int = 10000) -> MaxSATResult:
        """Find the maximum-weight satisfiable subset of constraints."""
        if not unique_constraints:
            return MaxSATResult(satisfied=[], excluded=[], total_weight=0, solve_time_ms=0.0)

        opt = z3.Optimize()
        opt.set("timeout", timeout_ms)

        indicators = []
        active_mask = []
        for i, uc in enumerate(unique_constraints):
            ind = z3.Bool(f"__ind_{i}")
            indicators.append(ind)
            try:
                if not z3.is_bool(uc.z3_formula):
                    active_mask.append(False)
                    continue
                opt.add(z3.Implies(ind, uc.z3_formula))
                opt.add_soft(ind, weight=uc.weight)
                active_mask.append(True)
            except Exception as e:
                logger.debug("Skipping constraint %d in MaxSAT: %s", i, e)
                active_mask.append(False)

        if not any(active_mask):
            return MaxSATResult(satisfied=[], excluded=list(unique_constraints),
                                total_weight=0, solve_time_ms=0.0)

        t0 = time.perf_counter()
        result = opt.check()
        solve_time = (time.perf_counter() - t0) * 1000

        satisfied = []
        excluded = []

        if result in (z3.sat, z3.unknown):
            model = opt.model()
            for i, uc in enumerate(unique_constraints):
                if not active_mask[i]:
                    excluded.append(uc)
                    continue
                val = model.evaluate(indicators[i], model_completion=True)
                if z3.is_true(val):
                    satisfied.append(uc)
                else:
                    excluded.append(uc)
        else:
            excluded = list(unique_constraints)

        total_w = sum(uc.weight for uc in satisfied)
        return MaxSATResult(
            satisfied=satisfied,
            excluded=excluded,
            total_weight=total_w,
            solve_time_ms=solve_time,
        )

"""
Invariant consensus scorer with A+C improvement:
  A (normal mode): score = positive_weight - alpha * negative_weight
  C (fallback mode): when satisfied_ratio < threshold, score = -excluded_exposure
"""
from __future__ import annotations

import logging
from collections import Counter

from .z3_maxsat import MaxSATResult

logger = logging.getLogger(__name__)


class InvariantScorer:

    def __init__(self, alpha: float = 0.5, fallback_threshold: float = 0.2):
        self.alpha = alpha
        self.fallback_threshold = fallback_threshold

    def score(
        self,
        maxsat_result: MaxSATResult,
        traces: list[dict],
        candidates: list[str],
    ) -> dict[str, float]:
        """Score each candidate answer using A+C strategy.

        Normal mode (A): score = Σw(satisfied ∩ traces) - α·Σw(excluded ∩ traces)
        Fallback mode (C): score = -Σw(excluded ∩ traces)
        Switches to fallback when satisfied_ratio < fallback_threshold.
        """
        answer_traces: dict[str, set[int]] = {}
        for t in traces:
            ans = str(t.get("answer", "")).strip()
            idx = t.get("trace_idx", 0)
            answer_traces.setdefault(ans, set()).add(idx)

        n_satisfied = len(maxsat_result.satisfied)
        n_excluded = len(maxsat_result.excluded)
        n_total = n_satisfied + n_excluded

        if n_total == 0:
            return {str(c).strip(): 0.0 for c in candidates}

        satisfied_ratio = n_satisfied / n_total
        fallback = satisfied_ratio < self.fallback_threshold

        logger.info(
            "Scorer mode=%s  satisfied_ratio=%.3f (%d/%d)  alpha=%.2f  threshold=%.2f",
            "FALLBACK" if fallback else "NORMAL",
            satisfied_ratio, n_satisfied, n_total,
            self.alpha, self.fallback_threshold,
        )

        scores: dict[str, float] = {}
        for cand in candidates:
            cand_key = str(cand).strip()
            cand_traces = answer_traces.get(cand_key, set())

            excluded_exposure = 0.0
            for uc in maxsat_result.excluded:
                if set(uc.source_traces) & cand_traces:
                    excluded_exposure += uc.weight

            if fallback:
                scores[cand_key] = -excluded_exposure
            else:
                positive = 0.0
                for uc in maxsat_result.satisfied:
                    if set(uc.source_traces) & cand_traces:
                        positive += uc.weight
                scores[cand_key] = positive - self.alpha * excluded_exposure

            logger.debug(
                "  candidate=%s  score=%.2f  traces=%s", cand_key, scores[cand_key], cand_traces,
            )

        return scores

    def select_answer(
        self,
        scores: dict[str, float],
        answer_counts: dict[str, int] | None = None,
    ) -> str:
        """Select the highest-scoring answer. Break ties by frequency."""
        if not scores:
            return ""
        max_score = max(scores.values())
        top = [a for a, s in scores.items() if s == max_score]
        if len(top) == 1:
            return top[0]
        if answer_counts:
            return max(top, key=lambda a: answer_counts.get(a, 0))
        return top[0]

